  "catalog/mechanisms/surface-reading/surface-reading.css": "/* Surface geometry owns the reading guide used by both content and toolbar identity. */\n:root {\n  --navigation-group-inset:9px;\n  --navigation-row-inset:10px;\n  --surface-reading-inset:var(--catalog-toolbar-inset,8px);\n}\n[data-catalog-workspace] {\n  --place-surface-inset:26px;\n  --place-content-inset:calc(var(--place-surface-inset) + 1rem);\n}\n[data-catalog-workspace]:has([data-slot=\"sidebar-wrapper\"][data-presentation=\"overlay\"]) { --place-surface-inset:18px; }\n[data-place] { --surface-reading-inset:var(--place-content-inset,42px); }\n[data-place][data-catalog-navigation] { --surface-reading-inset:calc(var(--navigation-group-inset) + var(--navigation-row-inset)); }\n[data-surface-frame], [data-picker-sheet] { --surface-reading-inset:var(--chrome-inset,1.25rem); }\n/* A compact frame caps one guide, not just its body padding. Its toolbar and\n   content consume the same value, including forms that add a wrapper. */\n@container (max-width:30rem) {\n  :is([data-surface-frame],[data-picker-sheet]) :is(.surface-content,[data-piece=\"toolbar\"]) {\n    --surface-reading-inset:min(var(--chrome-inset,1.25rem),20px);\n  }\n}\n@media (max-height:640px) {\n  [data-surface-frame], [data-picker-sheet] { --surface-reading-inset:min(var(--chrome-inset,1.25rem),20px); }\n}\n",
